'use strict';
// All places, facilities, fees and travel weights below are illustrative demo data.
const PLACES=[
 {id:'seoul',name:'서울역',x:210,y:245},{id:'hongdae',name:'홍대입구',x:120,y:115},
 {id:'city',name:'시청',x:300,y:190},{id:'jongno',name:'종로3가',x:410,y:125},
 {id:'ddp',name:'동대문역사문화공원',x:535,y:165},{id:'wang',name:'왕십리',x:635,y:225},
 {id:'seongsu',name:'성수',x:750,y:290},{id:'gangnam',name:'강남',x:600,y:385},
 {id:'yongsan',name:'용산',x:295,y:335}
];
const EDGES=[['seoul','hongdae',19],['seoul','city',5],['city','jongno',7],['jongno','ddp',8],['ddp','wang',9],['wang','seongsu',7],['seoul','yongsan',8],['yongsan','gangnam',21],['gangnam','seongsu',15],['hongdae','city',20]];
const LOCKERS=[
 {id:'l1',name:'서울역 A 보관함',place:'seoul',offset:[-20,-20],access:3,sizes:['S','M','L'],base:3500,extra:900,open:5,close:24,location:'예시 B1층 · 1번 출구 방향',kind:'지하철형'},
 {id:'l2',name:'홍대입구 B 보관함',place:'hongdae',offset:[22,17],access:4,sizes:['S','M'],base:3000,extra:800,open:6,close:23,location:'예시 B1층 · 3번 출구 방향',kind:'지하철형'},
 {id:'l3',name:'시청 C 보관함',place:'city',offset:[-19,23],access:2,sizes:['S','M','L'],base:2500,extra:1000,open:6,close:22,location:'예시 B1층 · 연결 통로',kind:'지하철형'},
 {id:'l4',name:'성수 D 보관함',place:'seongsu',offset:[-25,-22],access:3,sizes:['S','M','L'],base:4000,extra:800,open:7,close:23,location:'예시 B1층 · 2번 출구 방향',kind:'지하철형'},
 {id:'l5',name:'왕십리 E 보관함',place:'wang',offset:[12,-24],access:2,sizes:['S','M','L'],base:3000,extra:700,open:5,close:24,location:'예시 B1층 · 환승 통로',kind:'지하철형'},
 {id:'l6',name:'종로 F 보관소',place:'jongno',offset:[-9,-18],access:5,sizes:['S','M','L'],base:2500,extra:500,open:10,close:20,location:'예시 지상 1층 · 역 인근',kind:'매장형'}
];
const SIZE={S:{label:'소형',dim:'가로 40 × 깊이 50 × 높이 30cm',price:-1000},M:{label:'중형',dim:'가로 50 × 깊이 60 × 높이 50cm',price:0},L:{label:'대형',dim:'가로 50 × 깊이 60 × 높이 90cm',price:1200}};
const $=id=>document.getElementById(id);
const nameOf=id=>PLACES.find(p=>p.id===id)?.name||id;
const money=v=>new Intl.NumberFormat('ko-KR').format(v);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={mode:'near',size:'M',results:[],selected:null,saved:[],query:null};
try{const saved=JSON.parse(localStorage.getItem('jim-demo-compares')||'[]');if(Array.isArray(saved))state.saved=saved.filter(id=>LOCKERS.some(l=>l.id===id)).slice(0,3);}catch{}
function travel(from,to){
 const dist=Object.fromEntries(PLACES.map(p=>[p.id,Infinity]));const prev={};const todo=new Set(PLACES.map(p=>p.id));dist[from]=0;
 while(todo.size){const u=[...todo].sort((a,b)=>dist[a]-dist[b])[0];todo.delete(u);if(u===to)break;for(const [a,b,w] of EDGES){const v=a===u?b:b===u?a:null;if(v&&dist[u]+w<dist[v]){dist[v]=dist[u]+w;prev[v]=u;}}}
 const path=[to];while(path[0]!==from&&prev[path[0]])path.unshift(prev[path[0]]);return{minutes:dist[to],path};
}
function parseQuery(){return{start:$('start').value,visit:$('visit').value,end:$('end').value,size:state.size,deposit:new Date($('deposit').value),pickup:new Date($('pickup').value),priority:$('priority').value,mode:state.mode};}
function validate(q){if(!Number.isFinite(+q.deposit)||!Number.isFinite(+q.pickup))return'맡길 시각과 찾을 시각을 모두 입력해 주세요.';if(q.pickup<=q.deposit)return'찾을 시각은 맡길 시각보다 늦어야 해요.';if((q.pickup-q.deposit)>7*24*3600000)return'데모에서는 7일 이내의 보관 시간을 선택해 주세요.';if(q.mode==='route'&&q.visit===q.end)return'방문할 곳과 최종 목적지를 다르게 골라주세요.';return'';}
function operatingAt(l,date){const h=date.getHours()+date.getMinutes()/60;return h>=l.open&&h<l.close;}
function quote(l,q){const hours=(q.pickup-q.deposit)/3600000;return Math.max(0,l.base+SIZE[q.size].price)+Math.max(0,Math.ceil(hours-4))*l.extra;}
function calculate(q){
 const direct=travel(q.start,q.visit).minutes+travel(q.visit,q.end).minutes;
 return LOCKERS.filter(l=>l.sizes.includes(q.size)&&operatingAt(l,q.deposit)&&operatingAt(l,q.pickup)).map(l=>{
  const near=travel(q.start,l.place).minutes+l.access;
  const outbound=travel(l.place,q.visit).minutes+l.access;
  const back=travel(q.visit,l.place).minutes+l.access;
  const last=travel(l.place,q.end).minutes+l.access;
  return{...l,near,outbound,back,last,total:near+outbound+back+last,carry:near+last,detour:Math.max(0,near+outbound+back+last-direct),price:quote(l,q),hours:(q.pickup-q.deposit)/3600000};
 });
}
function sortedResults(){const q=state.query;const sort=$('sort').value;const rank=sort==='near'?'near':sort==='price'?'price':sort==='total'?'total':q.mode==='near'?'near':q.priority==='carry'?'carry':q.priority==='price'?'price':'total';return[...state.results].sort((a,b)=>a[rank]-b[rank]||a.near-b.near);}
function setMode(mode){state.mode=mode;const route=mode==='route';$('nearTab').classList.toggle('active',!route);$('routeTab').classList.toggle('active',route);$('nearTab').setAttribute('aria-selected',String(!route));$('routeTab').setAttribute('aria-selected',String(route));$('routeFields').hidden=!route;$('priorityField').hidden=!route;$('modeEyebrow').textContent=route?'PLAN MY DAY':'NEAR ME';$('modeTitle').textContent=route?'찾으러 가는 길까지, 한 번에.' :'일단, 짐부터 내려놓을까요?';$('modeDescription').textContent=route?'방문과 회수, 마지막 목적지까지 비교해요.':'출발지에서 가까운 보관함을 비교해요.';$('searchText').textContent=route?'내 일정에 맞는 보관함 찾기':'가까운 보관함 찾기';$('sort').value='recommended';}
function search(){const q=parseQuery();const error=validate(q);$('formError').textContent=error;if(error)return false;state.query=q;state.results=calculate(q);const sorted=sortedResults();state.selected=sorted[0]?.id||null;renderResults();return true;}
function renderResults(){
 const items=sortedResults();const route=state.query.mode==='route';$('resultsTitle').innerHTML=`${route?'내 일정에 맞는':'가까운'} 보관함 <span>${items.length}</span>`;
 $('resultCaption').textContent=`${SIZE[state.query.size].label} · 선택한 맡김/회수 시각에 운영하는 가상 시설 · 빈자리 미확인`;
 const summary=$('summary');summary.classList.toggle('visible',route&&items.length>0);
 if(route&&items.length){const best=items[0];const nearest=[...items].sort((a,b)=>a.near-b.near)[0];const saved=nearest.total-best.total;summary.innerHTML=`<strong>${nameOf(state.query.start)} → ${nameOf(state.query.visit)} → ${nameOf(state.query.end)}</strong><br>${saved>0?`가장 가까운 후보보다 전체 이동이 <strong>${saved}분 줄어드는</strong> 선택이에요.`:`선택한 우선순위에 따라 <strong>${escapeHtml(best.name)}</strong>이 먼저 표시돼요.`}<small>시간은 예시 그래프의 이동시간과 보관소 접근시간 합계입니다. 머무는 시간·실시간 대기는 포함하지 않아요.</small>`;}
 $('cards').innerHTML=items.length?items.map((l,i)=>`<article class="locker-card ${l.id===state.selected?'selected':''}" data-id="${l.id}"><div class="card-top"><div class="locker-icon" aria-hidden="true">▥</div><div class="card-title"><div class="card-tags">${i===0?`<span class="tag recommend">${route?'선택 기준 추천':'가장 가까운 후보'}</span>`:''}<span class="tag">${l.kind} · 예시</span><span class="tag unknown">빈자리 확인 필요</span></div><h3>${escapeHtml(l.name)}</h3><p>${escapeHtml(l.location)}</p></div><button class="save-button ${state.saved.includes(l.id)?'saved':''}" data-save="${l.id}" aria-label="${escapeHtml(l.name)} 비교함 ${state.saved.includes(l.id)?'제거':'추가'}" aria-pressed="${state.saved.includes(l.id)}">${state.saved.includes(l.id)?'✓':'+'}</button></div><div class="metrics"><div class="metric"><small>${route?'전체 이동':'출발지에서 이동'}</small><strong>${route?l.total:l.near}<em>분</em></strong><small class="note">${route?'맡김·방문·회수·최종 이동':'예시 교통+접근시간'}</small></div><div class="metric"><small>${route?'짐 동반 이동':'보관함 크기'}</small><strong>${route?l.carry:SIZE[state.query.size].label}${route?'<em>분</em>':''}</strong><small class="note">${route?'맡기기 전 + 찾은 후':'선택 크기 수용 가능'}</small></div><div class="metric"><small>예상 보관료</small><strong>${money(l.price)}<em>원</em></strong><small class="note">가상 요금 · ${l.hours.toFixed(1)}시간</small></div></div><div class="card-bottom"><span>◷ ${String(l.open).padStart(2,'0')}:00 – ${l.close===24?'24:00':String(l.close).padStart(2,'0')+':00'} · 선택 시각 운영</span><button data-detail="${l.id}">동선 자세히 <span>↗</span></button></div></article>`).join(''):`<div class="empty"><h3>지금 조건에 맞는 예시 보관함이 없어요.</h3><p>맡기거나 찾는 시각이 운영시간 밖이거나,<br>선택한 크기를 지원하지 않는 경우예요.<br>시간이나 짐 크기를 바꿔 다시 찾아보세요.</p><button class="secondary" id="resetExample">기본 예시로 돌아가기</button></div>`;
 updateCompareCount();renderMap();
}
function toggleSave(id){if(state.saved.includes(id))state.saved=state.saved.filter(x=>x!==id);else{if(state.saved.length>=3){toast('최대 3곳까지 비교할 수 있어요. 기존 후보를 먼저 빼주세요.');return;}state.saved.push(id);}try{localStorage.setItem('jim-demo-compares',JSON.stringify(state.saved));}catch{}renderResults();if($('compareDialog').open)renderComparison();}
function updateCompareCount(){$('compareCount').textContent=state.saved.length;}
function detail(id){const l=state.results.find(x=>x.id===id);if(!l)return;state.selected=id;renderResults();const q=state.query;const route=q.mode==='route';
 const legs=route?[[nameOf(q.start),`${l.near}분 · 짐을 들고 이동`],[l.name,`${l.outbound}분 · 짐 없이 방문 장소로 이동`],[nameOf(q.visit),`${l.back}분 · 보관함으로 돌아오기`],[`${l.name} · 짐 회수`,`${l.last}분 · 짐을 들고 최종 목적지로 이동`],[nameOf(q.end),'일정 마무리']]:[[nameOf(q.start),`${l.near}분 · 예시 교통+보관함 접근시간`],[l.name,'선택한 시각에 보관하고 회수 · 빈자리 확인 필요']];
 $('detailContent').innerHTML=`<div class="dialog-heading"><span class="step-label">YOUR ROUTE / 예시 동선</span><button class="close-button" data-close="detailDialog" aria-label="닫기">×</button></div><h2>${escapeHtml(l.name)}</h2><p>${escapeHtml(l.location)} · 실제 시설 정보가 아닌 데모용 가상 보관함</p><div class="detail-grid"><div><small>${route?'전체 이동 / 짐 동반 이동':'출발지에서 이동'}</small><strong>${route?l.total+'분 / '+l.carry+'분':l.near+'분'}</strong></div><div><small>예상 보관료</small><strong>${money(l.price)}원 · 가상 요금</strong></div><div><small>${SIZE[q.size].label} 규격 · 예시</small><strong>${SIZE[q.size].dim}</strong></div><div><small>빈자리</small><strong>확인 불가 · 실제 연동 필요</strong></div></div><ol class="timeline">${legs.map(([title,note])=>`<li><strong>${escapeHtml(title)}</strong><small>${escapeHtml(note)}</small></li>`).join('')}</ol><p class="info-callout">${route?`직접 이동(${nameOf(q.start)} → ${nameOf(q.visit)} → ${nameOf(q.end)}) 대비 추가 이동 ${l.detour}분. `:''}실제 경로나 시간표를 조회한 결과가 아닙니다. 예약·결제 기능은 없습니다.</p><div class="detail-actions"><button class="secondary" id="copyPlan" data-copy="${l.id}">일정 복사</button><button class="primary" data-detail-save="${l.id}">${state.saved.includes(id)?'비교함에서 빼기':'비교함에 추가'}</button></div>`;
 if(!$('detailDialog').open)$('detailDialog').showModal();
}
async function copyPlan(id){const l=state.results.find(x=>x.id===id);if(!l)return;const q=state.query;const text=`[오늘의 짐 / 가상 데모]\n${q.mode==='route'?`${nameOf(q.start)} → ${l.name}(보관) → ${nameOf(q.visit)} → ${l.name}(회수) → ${nameOf(q.end)}`:`${nameOf(q.start)} → ${l.name}`}\n보관: ${$('deposit').value.replace('T',' ')} ~ ${$('pickup').value.replace('T',' ')}\n${SIZE[q.size].label} / 가상 보관료 ${money(l.price)}원\n이동시간은 예시 계산이며 실시간 빈자리·실제 시설 정보가 아닙니다.`;try{await navigator.clipboard.writeText(text);toast('가상 데모 표시를 포함한 일정을 복사했어요.');}catch{toast('브라우저에서 복사를 허용하지 않았어요. 화면의 일정을 확인해 주세요.');}}
function renderComparison(){const q=state.query;const all=calculate(q);const rows=state.saved.map(id=>all.find(l=>l.id===id)||{...LOCKERS.find(l=>l.id===id),unavailable:true});$('comparison').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr><th>가상 보관함</th><th>출발 이동</th>${q.mode==='route'?'<th>전체 이동</th><th>짐 동반</th>':''}<th>보관료</th></tr></thead><tbody>${rows.map(l=>`<tr><td><strong>${escapeHtml(l.name)}</strong><button data-save="${l.id}">제거</button></td>${l.unavailable?`<td colspan="${q.mode==='route'?4:2}">현재 크기·시간 조건에 맞지 않음</td>`:`<td>${l.near}분</td>${q.mode==='route'?`<td>${l.total}분</td><td>${l.carry}분</td>`:''}<td>${money(l.price)}원</td>`}</tr>`).join('')}</tbody></table></div><p class="subtle">현재 검색을 실행한 조건으로 계산합니다. 입력값 변경 후 검색하면 비교 값도 갱신돼요.</p>`:'<div class="empty"><h3>비교할 보관함을 골라주세요.</h3><p>결과 카드의 + 버튼으로 최대 3곳까지 담을 수 있어요.</p></div>';}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function renderMap(){
 const q=state.query;const selected=state.results.find(l=>l.id===state.selected);const placeById=id=>PLACES.find(p=>p.id===id);
 const edges=EDGES.map(([a,b])=>{const p=placeById(a),r=placeById(b);return`<path d="M${p.x} ${p.y} L${r.x} ${r.y}" fill="none" stroke="#fdfef9" stroke-width="13"/><path d="M${p.x} ${p.y} L${r.x} ${r.y}" fill="none" stroke="#d7e1d0" stroke-width="1"/>`;}).join('');
 const activeLegs=selected?(q.mode==='route'?[[q.start,selected.place],[selected.place,q.visit],[q.visit,selected.place],[selected.place,q.end]]:[[q.start,selected.place]]):[];
 const paths=activeLegs.map(([a,b],i)=>{const points=travel(a,b).path.map(id=>{const p=placeById(id);return`${p.x},${p.y}`;}).join(' ');return`<polyline points="${points}" fill="none" stroke="${i===1||i===2?'#c18c6b':'#427956'}" stroke-width="${i===1||i===2?'3':'4'}" stroke-dasharray="${i===1||i===2?'7 5':'none'}" opacity=".78" stroke-linecap="round"/>`;}).join('');
 const nodes=PLACES.map(p=>`<g><circle cx="${p.x}" cy="${p.y}" r="4" fill="#fdfef9" stroke="#b5c4aa" stroke-width="2"/><text class="map-text" x="${p.x+8}" y="${p.y+17}" font-size="11" fill="#9aa68e">${p.name}</text></g>`).join('');
 const availableIds=new Set(state.results.map(l=>l.id));const pins=LOCKERS.map(l=>{const p=placeById(l.place),x=p.x+l.offset[0],y=p.y+l.offset[1],isSelected=l.id===state.selected,available=availableIds.has(l.id);return`<g class="map-node" data-map-id="${l.id}" tabindex="${available?'0':'-1'}" role="button" aria-label="${escapeHtml(l.name)} ${available?'동선 보기':'현재 조건에서 제외'}" transform="translate(${x},${y})" opacity="${available?'1':'.35'}"><rect x="-14" y="-19" width="28" height="29" rx="8" fill="${isSelected?'#2e6144':'#fffef8'}" stroke="${isSelected?'#2e6144':'#a6ba99'}" stroke-width="1.5"/><text x="0" y="1" text-anchor="middle" font-size="19" fill="${isSelected?'#fff':'#7e9a6c'}">▥</text>${isSelected?`<rect x="-58" y="-45" width="116" height="22" rx="5" fill="#fffef8" stroke="#d0dfc5"/><text class="map-text map-pin-label" x="0" y="-30" text-anchor="middle">${escapeHtml(l.name)}</text>`:''}</g>`;}).join('');
 const point=(id,label,color,dy)=>{const p=placeById(id);return`<g transform="translate(${p.x},${p.y+dy})"><circle r="7" fill="${color}" stroke="white" stroke-width="3"/><rect x="10" y="-13" width="${label.length*11+17}" height="25" rx="6" fill="white" stroke="#e0e7d9"/><text class="map-text" x="18" y="3" fill="${color}" font-size="11" font-weight="600">${label}</text></g>`;};
 $('map').innerHTML=`<defs><pattern id="blocks" width="64" height="52" patternUnits="userSpaceOnUse" patternTransform="rotate(-19)"><rect width="64" height="52" fill="#eaf0e4"/><rect x="4" y="4" width="48" height="36" rx="4" fill="#e2e9da"/><path d="M0 48H64 M60 0V52" stroke="#f5f7ef" stroke-width="6"/></pattern></defs><rect width="900" height="440" fill="url(#blocks)"/><path d="M-20 295 C140 270 175 365 355 310 S600 310 920 390" stroke="#d5e5df" stroke-width="63" fill="none"/><path d="M-20 295 C140 270 175 365 355 310 S600 310 920 390" stroke="#eaf3ed" stroke-width="2" fill="none"/><text x="480" y="326" font-size="11" fill="#9eb4ab" letter-spacing="7" transform="rotate(12 480 326)">한 강</text><ellipse cx="475" cy="60" rx="110" ry="38" fill="#d8e5ca"/><ellipse cx="70" cy="220" rx="42" ry="70" fill="#dae6cf"/>${edges}${paths}${nodes}${pins}${point(q.start,'출발 · '+nameOf(q.start),'#356944',0)}${q.mode==='route'?point(q.visit,'방문 · '+nameOf(q.visit),'#bd815f',15)+point(q.end,'마지막 · '+nameOf(q.end),'#5c7282',-18):''}`;
}
function init(){for(const id of ['start','visit','end'])$(id).innerHTML=PLACES.map(p=>`<option value="${p.id}">${p.name}</option>`).join('');$('start').value='seoul';$('visit').value='seongsu';$('end').value='hongdae';setDates();setMode('near');search();}
function setDates(){const now=new Date();const localDate=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;$('deposit').value=localDate+'T13:00';$('pickup').value=localDate+'T17:00';}
function example(){setMode('route');state.size='M';document.querySelectorAll('[data-size]').forEach(b=>{b.classList.toggle('active',b.dataset.size==='M');b.setAttribute('aria-pressed',String(b.dataset.size==='M'));});$('start').value='seoul';$('visit').value='seongsu';$('end').value='hongdae';$('priority').value='total';setDates();search();toast('같은 일정에서 가까운 순서와 전체 이동시간 순서를 비교해보세요.');}
$('plannerForm').addEventListener('submit',e=>{e.preventDefault();search();});
$('nearTab').addEventListener('click',()=>{setMode('near');search();});$('routeTab').addEventListener('click',()=>{setMode('route');search();});
document.querySelectorAll('[data-size]').forEach(b=>b.addEventListener('click',()=>{state.size=b.dataset.size;document.querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});}));
$('sort').addEventListener('change',()=>{state.selected=sortedResults()[0]?.id||null;renderResults();});
$('exampleButton').addEventListener('click',example);$('aboutButton').addEventListener('click',()=>$('infoDialog').showModal());$('apiButton').addEventListener('click',()=>$('apiDialog').showModal());
$('compareButton').addEventListener('click',()=>{renderComparison();$('compareDialog').showModal();});
$('resetMap').addEventListener('click',()=>{state.selected=sortedResults()[0]?.id||null;renderResults();toast('현재 검색의 추천 후보를 표시했어요.');});
$('sizeHelp').addEventListener('click',()=>toast('예시 규격: 소형 40×50×30 / 중형 50×60×50 / 대형 50×60×90cm. 실제 시설 규격이 아닙니다.'));
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();const save=e.target.closest('[data-save]');if(save)toggleSave(save.dataset.save);const dsave=e.target.closest('[data-detail-save]');if(dsave){toggleSave(dsave.dataset.detailSave);detail(dsave.dataset.detailSave);}const d=e.target.closest('[data-detail]');if(d)detail(d.dataset.detail);const copy=e.target.closest('[data-copy]');if(copy)copyPlan(copy.dataset.copy);const pin=e.target.closest('[data-map-id]');if(pin){if(state.results.some(l=>l.id===pin.dataset.mapId))detail(pin.dataset.mapId);else toast('선택한 짐 크기 또는 맡김·회수 시각에 맞지 않는 예시 시설이에요.');}if(e.target.id==='resetExample')example();});
$('map').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const pin=e.target.closest('[data-map-id]');if(pin){e.preventDefault();detail(pin.dataset.mapId);}}});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}}));
init();
